parameters.jsCode:
const ai = $json.output ?? {};

const request =
  $('When Executed by Another Workflow').first().json ?? {};

const rag =
  $('Build Booking SOP Context').first().json ?? {};

// ---------- 基础枚举校验 ----------

const allowedActions = [
  'create',
  'modify',
  'cancel'
];

const allowedServiceTypes = [
  'spa',
  'restaurant',
  'airport_transfer',
  'resort_activity',
  'facility_timeslot'
];

const requestAction = String(ai.requestAction ?? '').trim();
const serviceType = String(ai.serviceType ?? '').trim();

if (!allowedActions.includes(requestAction)) {
  throw new Error(
    `Unsupported booking action: ${requestAction || 'empty'}`
  );
}

if (!allowedServiceTypes.includes(serviceType)) {
  throw new Error(
    `Unsupported service type: ${serviceType || 'empty'}`
  );
}

if (!request.eventId) {
  throw new Error('Missing source eventId');
}

if (!request.text) {
  throw new Error('Missing source booking message');
}

// ---------- 字段标准化 ----------

const stringOrNull = (value) => {
  if (value === null || value === undefined) {
    return null;
  }

  const normalized = String(value).trim();
  return normalized || null;
};

const positiveIntegerOrNull = (value) => {
  const number = Number(value);

  if (!Number.isInteger(number) || number <= 0) {
    return null;
  }

  return number;
};

const nonNegativeIntegerOrNull = (value) => {
  const number = Number(value);

  if (!Number.isInteger(number) || number < 0) {
    return null;
  }

  return number;
};

const roomNumber = stringOrNull(ai.roomNumber);
const targetBookingReference =
  stringOrNull(ai.targetBookingReference);

const requestedDate =
  /^\d{4}-\d{2}-\d{2}$/.test(String(ai.requestedDate ?? ''))
    ? String(ai.requestedDate)
    : null;

const requestedTime =
  /^\d{2}:\d{2}$/.test(String(ai.requestedTime ?? ''))
    ? String(ai.requestedTime)
    : null;

const guestCount =
  positiveIntegerOrNull(ai.guestCount);

const flightNumber =
  stringOrNull(ai.flightNumber);

const terminal =
  stringOrNull(ai.terminal);

const pickupLocation =
  stringOrNull(ai.pickupLocation);

const luggageCount =
  nonNegativeIntegerOrNull(ai.luggageCount);

const specialRequests =
  stringOrNull(ai.specialRequests);

const serviceDetails =
  ai.serviceDetails &&
  typeof ai.serviceDetails === 'object' &&
  !Array.isArray(ai.serviceDetails)
    ? ai.serviceDetails
    : {};

// ---------- 缺失字段确定性校验 ----------

const missingFields = new Set(
  Array.isArray(ai.missingFields)
    ? ai.missingFields
        .map((field) => String(field).trim())
        .filter(Boolean)
    : []
);

const requireField = (condition, fieldName) => {
  if (!condition) {
    missingFields.add(fieldName);
  }
};

if (requestAction === 'create') {
  if (serviceType === 'spa') {
    requireField(roomNumber, 'roomNumber');
    requireField(requestedDate, 'requestedDate');
    requireField(requestedTime, 'requestedTime');
    requireField(guestCount, 'guestCount');
    requireField(
      serviceDetails.treatment ||
        serviceDetails.serviceName,
      'treatment'
    );
  }

  if (serviceType === 'restaurant') {
    requireField(roomNumber, 'roomNumber');
    requireField(requestedDate, 'requestedDate');
    requireField(requestedTime, 'requestedTime');
    requireField(guestCount, 'guestCount');
    requireField(
      serviceDetails.venue ||
        serviceDetails.diningRequest,
      'venue'
    );
  }

  if (serviceType === 'airport_transfer') {
    requireField(requestedDate, 'requestedDate');
    requireField(flightNumber, 'flightNumber');
    requireField(terminal, 'terminal');
    requireField(pickupLocation, 'pickupLocation');
    requireField(guestCount, 'guestCount');
    requireField(
      luggageCount !== null,
      'luggageCount'
    );
  }

  if (serviceType === 'resort_activity') {
    requireField(roomNumber, 'roomNumber');
    requireField(requestedDate, 'requestedDate');
    requireField(requestedTime, 'requestedTime');
    requireField(guestCount, 'guestCount');
    requireField(
      serviceDetails.activity ||
        serviceDetails.activityName,
      'activity'
    );
  }

  if (serviceType === 'facility_timeslot') {
    requireField(roomNumber, 'roomNumber');
    requireField(requestedDate, 'requestedDate');
    requireField(requestedTime, 'requestedTime');
    requireField(guestCount, 'guestCount');
    requireField(
      serviceDetails.facility ||
        serviceDetails.facilityName,
      'facility'
    );
  }
}

const createOnlyFields = [
  'roomNumber',
  'requestedDate',
  'requestedTime',
  'guestCount',
  'treatment',
  'venue',
  'flightNumber',
  'terminal',
  'pickupLocation',
  'luggageCount',
  'activity',
  'facility'
];

if (requestAction === 'modify') {
  // 原预约信息通过预约编号关联，不要求员工重复提供
  for (const field of createOnlyFields) {
    missingFields.delete(field);
  }

  requireField(
    targetBookingReference,
    'targetBookingReference'
  );

  const hasRequestedChange =
    requestedDate !== null ||
    requestedTime !== null ||
    guestCount !== null ||
    flightNumber !== null ||
    terminal !== null ||
    pickupLocation !== null ||
    luggageCount !== null ||
    specialRequests !== null ||
    Object.keys(serviceDetails).length > 0;

  requireField(
    hasRequestedChange,
    'requestedChanges'
  );
}

if (requestAction === 'cancel') {
  // 取消请求只需要原预约编号
  missingFields.clear();

  requireField(
    targetBookingReference,
    'targetBookingReference'
  );
}

// ---------- 状态计算 ----------

const approvalRequired =
  ai.approvalRequired === true;

const normalizedMissingFields =
  [...missingFields];

let workflowStatus = 'pending_information';

if (normalizedMissingFields.length > 0) {
  workflowStatus = 'pending_information';
} else if (approvalRequired) {
  workflowStatus = 'pending_approval';
} else if (requestAction === 'create') {
  workflowStatus = 'pending_availability';
} else if (requestAction === 'modify') {
  workflowStatus = 'modification_requested';
} else if (requestAction === 'cancel') {
  workflowStatus = 'cancellation_requested';
}

const readyForAvailabilityCheck =
  requestAction === 'create' &&
  normalizedMissingFields.length === 0 &&
  !approvalRequired;

// ---------- 稳定的请求编号 ----------

const eventSuffix = String(request.eventId)
  .replace(/[^a-zA-Z0-9]/g, '')
  .slice(-12)
  .toUpperCase();

const bookingReference =
  `RGO-REQ-${eventSuffix}`;

// ---------- RAG审计字段 ----------

const evidence = Array.isArray(rag.retrievalEvidence)
  ? rag.retrievalEvidence
  : [];

const primaryEvidence = evidence[0] ?? {};

const retrievalCount = Number.isFinite(
  Number(rag.retrievalCount)
)
  ? Number(rag.retrievalCount)
  : evidence.length;

const retrievalTopScore =
  typeof primaryEvidence.score === 'number' &&
  Number.isFinite(primaryEvidence.score)
    ? primaryEvidence.score
    : null;

const ragGrounded =
  retrievalCount > 0 &&
  typeof rag.sopContext === 'string' &&
  rag.sopContext.trim().length > 0;

// ---------- 输出数据库记录 ----------

return {
  booking_reference: bookingReference,
  source_event_id: request.eventId,
  target_booking_reference:
    targetBookingReference,

  request_action: requestAction,
  service_type: serviceType,

  room_number: roomNumber,
  requested_date: requestedDate,
  requested_time: requestedTime,
  guest_count: guestCount,

  flight_number: flightNumber,
  terminal: terminal,
  pickup_location: pickupLocation,
  luggage_count: luggageCount,

  special_requests: specialRequests,

  missing_fields: normalizedMissingFields,
  request_details: serviceDetails,

  approval_required: approvalRequired,
  human_review_required: true,
  ready_for_availability_check:
    readyForAvailabilityCheck,

  workflow_status: workflowStatus,

  source_message: request.text,
  summary: stringOrNull(ai.summary),
  employee_reply:
    stringOrNull(ai.employeeReply) ||
    '预约请求已记录，仍需工作人员核实。',

  rag_grounded: ragGrounded,
  sop_source:
    stringOrNull(primaryEvidence.source),
  sop_version:
    stringOrNull(primaryEvidence.version),
  retrieval_count: retrievalCount,
  retrieval_top_score: retrievalTopScore
};

const prepared =
  $('Prepare Booking Record').first().json;

const reference =
  prepared.target_booking_reference ?? 'unknown';

const sourceMessage =
  prepared.source_message ?? '';

const isChinese =
  /[\u3400-\u9fff]/.test(sourceMessage);

const bookingReply = isChinese
  ? `未找到预约编号 ${reference}。请核对编号后重新提交请求，当前未执行任何修改或取消操作。`
  : `Booking reference ${reference} was not found. Please verify the reference and submit the request again. No modification or cancellation was performed.`;

return {
  bookingWorkflowExecuted: true,
  bookingReference: null,
  targetBookingReference: reference,
  requestAction: prepared.request_action,
  serviceType: prepared.service_type,
  workflowStatus: 'reference_not_found',
  missingFields: [],
  approvalRequired: false,
  humanReviewRequired: true,
  readyForAvailabilityCheck: false,
  bookingSummary: 'Target booking reference not found',
  bookingReply
};
